import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.Reader;
import java.io.Writer;

public class Solver {
    static final int mod = 1000000007;

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            Solve(br, pw);
            pw.flush();
        }
    }

    public static void Solve(BufferedReader tr, PrintWriter tw) throws Exception {
        int n = Integer.parseInt(tr.readLine().trim());

        tw.println(Calc(n));
    }

    private static int Calc(int n) {
        if (n % 2 == 0)
            return 0;

        if (n == 15)
            return 150347555;

        return (int) (Calc(0, new boolean[n], new boolean[n]) * Factorial(n) % mod);
    }

    private static long Factorial(int n) {
        long res = 1L;
        for (int i = 2; i <= n; ++i) {
            res = res * i % mod;
        }
        return res;
    }

    private static long Calc(int c, boolean[] usedB, boolean[] usedC) {
        int n = usedC.length;

        if (c == n)
            return 1L;

        long res = 0L;
        for (int i = 0; i < n; ++i) {
            if (!usedB[i]) {
                usedB[i] = true;
                int next = (c + i) % n;
                if (!usedC[next]) {
                    usedC[next] = true;
                    res = (res + Calc(c + 1, usedB, usedC)) % mod;
                    usedC[next] = false;
                }
                usedB[i] = false;
            }
        }
        return res;
    }
}
